/**
 * New Creation
 * ------------
 * The Lord promises new heavens and a new earth, where the wolf and lamb feed together and the city needs no sun. Stage: a rebuilt city on a hill, a lion and a lamb at its gate, children in the streets; warm, golden, endless light.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: lion
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./isaiah-kit.js.
 */

import { THREE, createScene, cityGate, house, sheep, lion, person } from './isaiah-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3379568678, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x050302), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [12, 0, -58], { name: 'city', r: [0, -0.10, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* flock: sheep grazing */
    sheep(W, group, 16.0, 0, -9.6, W.r() * 6, 1.03);
    sheep(W, group, 17.5, 0, 7.6, W.r() * 6, 0.98);
    sheep(W, group, 2.6, 0, 1.4, W.r() * 6, 1.00);
    sheep(W, group, 1.7, 0, 8.4, W.r() * 6, 1.14);
    sheep(W, group, -9.2, 0, 3.6, W.r() * 6, 0.94);
    sheep(W, group, -4.1, 0, -0.3, W.r() * 6, 0.90);
    /* lion: the danger in the scene */
    lion(W, group, -7.8, 0, -4.2, 1.1, { ry: 0.66 });

    /* hero: the lion */
    lion(W, group, 0, 0, 0, 1.35, { ry: 0.4 });
    W.disc([0, 5, -12], 6, 0x2f2215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241a10, ry: -0.02, s: 1.19 });

    return W.finish();
}

export default { build };
